const Actions=require('../.operational-tests/components/HomeStudentActions').default;
const React=require('react'),{renderToStaticMarkup}=require('react-dom/server');
let count=0;function test(name,fn){fn();console.log('OK '+(++count)+' '+name);}
const base=()=>({version:1,currentCompetence:'2026-09',competences:{'2026-09':{status:'OPEN'}},dsPercent:50,rankingByCompetence:{},personalInvoices:[],dsKids:[],dsReceipts:{},expenses:[],extraExpenses:[],categories:[],history:[]});
