const next=(data,month)=>apply(data,{type:'CREATE_NEXT_COMPETENCE',fromCompetence:month});
test('início outubro sem lançamento em setembro',()=>{const d=create(base());assert.equal(d.expenses[0].competence,'2026-10');assert.equal(d.expenses[0].dueDay,10);assert.equal(d.currentCompetence,'2026-10');});
