test('parcelas avançam e terminam',()=>{let d=create(base(),{kind:'INSTALLMENT',installmentCurrent:1,installmentTotal:2});d=next(d,'2026-10');assert.equal(d.expenses.at(-1).installmentCurrent,2);assert.equal(next(d,'2026-11').expenses.length,2);});
test('datas e parcelas inválidas rejeitadas',()=>{for(const x of [{startCompetence:'2026-13'},{dueDay:0},{kind:'INSTALLMENT',installmentCurrent:3,installmentTotal:2}]){const b=base();assert.equal(create(b,x),b);}});
