test('exclusão de parcela mantém progressão',()=>{let d=create(base(),{kind:'INSTALLMENT',installmentCurrent:1,installmentTotal:2});d=apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id});assert.equal(next(d,'2026-10').expenses[0].installmentCurrent,2);});
test('série excluída não retorna',()=>{let d=create(base());let id=d.expenses[0].id;d=next(d,'2026-10');d=apply(d,{type:'EXPENSE_DELETE',id,scope:'CURRENT_AND_FUTURE'});assert.equal(d.expenses.length,0);assert.equal(next(d,'2026-11').expenses.length,0);assert.ok(d.history.length);});
test('pagamentos e meses fechados protegidos na série',()=>{let d=create(base());let id=d.expenses[0].id;d=next(d,'2026-10');d=next(d,'2026-11');d.expenses[1].payments=[{id:'p',date:'2026-11-10',amount:100}];d.competences['2026-12'].status='CLOSED';let saved=JSON.stringify(d.expenses.slice(1));d=apply(d,{type:'EXPENSE_DELETE',id,scope:'CURRENT_AND_FUTURE'});assert.equal(JSON.stringify(d.expenses),saved);});
test('ocorrência paga não excluída',()=>{let d=create(base());d.expenses[0].payments=[{id:'p',amount:10}];assert.equal(apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id}),d);});
test('contas com mesmo nome não misturadas',()=>{let d=create(create(base()));const keep=d.expenses[1].id;d=apply(d,{type:'EXPENSE_DELETE',id:d.expenses[0].id,scope:'CURRENT_AND_FUTURE'});assert.equal(d.expenses[0].id,keep);});
